public class WeatherPollingService : BackgroundService
{
    private readonly ILogger<WeatherPollingService> _logger;
    private readonly IServiceProvider _services;
    private readonly TimeSpan _interval = TimeSpan.FromMinutes(5);

    public WeatherPollingService(ILogger<WeatherPollingService> logger, IServiceProvider services)
    {
        _logger = logger;
        _services = services;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _logger.LogInformation("Weather polling service started");

        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                using var scope = _services.CreateScope();
                var client = scope.ServiceProvider.GetRequiredService<WeatherApiClient>();
                var forecast = await client.GetForecastAsync(stoppingToken);

                // Update cache or database here
                _logger.LogInformation("Updated weather forecast at {Time}", DateTimeOffset.Now);
            }
            catch (Exception ex) when (!stoppingToken.IsCancellationRequested)
            {
                _logger.LogError(ex, "Failed to update weather forecast");
            }

            await Task.Delay(_interval, stoppingToken);
        }

        _logger.LogInformation("Weather polling service stopped");
    }
}

